var i=`0400-beef-wellington`;var o=`world-0400`;var n=`GB`;var a=`northern-europe`;var r=4;var s=108;var l={en:`Beef Wellington`,ua:`Яловичина Веллінгтон`};var d={en:`A traditional United Kingdom dish made with beef tenderloin, dijon mustard, button mushroom, shallot. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Велика Британія. Основні інгредієнти: яловича вирізка, діжонська гірчиця, печериця, цибуля шалот. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Pat the beef fillet dry, season and sear in a very hot pan with olive oil until browned all over; cool and brush with mustard.`,ua:`Обсушіть яловиче філе, приправте й швидко підрум’яньте з усіх боків на дуже гарячій сковороді з олією; остудіть і змастіть гірчицею.`,t:[`searing`],m:11,i:[[`beef-tenderloin`,900,`g`],[`extra-virgin-olive-oil`,40,`ml`],[`dijon-mustard`,55,`g`]]},{en:`Cook finely chopped mushrooms and shallots with butter until every trace of moisture evaporates and the duxelles is dry; cool completely.`,ua:`Обсмажуйте дрібно нарізані гриби й шалот із маслом до повного випаровування вологи та сухої консистенції дюкселю; повністю остудіть.`,t:[`chopping`,`sauteing`],m:14,i:[[`button-mushroom`,600,`g`],[`shallot`,140,`g`],[`unsalted-butter`,65,`g`],[`thyme`,3,`sprig`]]},{en:`Cover cooled beef with cold mushroom duxelles, wrap tightly in prosciutto and then in puff pastry; seal the edges underneath.`,ua:`Покрийте охолоджену яловичину грибним дюкселем, щільно загорніть у прошуто, а потім у листкове тісто; закрийте шви знизу.`,t:[`rolling-stuffed-food`],m:16,i:[[`prosciutto-crudo`,190,`g`],[`puff-pastry`,550,`g`]]},{en:`Chill the tightly wrapped raw Wellington seam-side down for at least 30 minutes, to help the pastry hold its shape.`,ua:`Охолоджуйте щільно загорнутий сирий Веллінгтон швом донизу щонайменше 30 хвилин, щоб тісто зберегло форму.`,t:[`rapid-chilling`],m:30,i:[]},{en:`Brush the pastry with beaten egg and bake at 200°C until golden and the beef reaches a safe internal temperature measured at its center; rest briefly before slicing.`,ua:`Змастіть тісто збитим яйцем і випікайте при 200°C до золотавості та безпечної внутрішньої температури яловичини в центрі; дайте недовго відпочити перед нарізанням.`,t:[`roasting`],m:37,i:[[`chicken-egg`,1,`pcs`]]}];var h={slug:i,id:o,country:`GB`,region:a,servings:4,minutes:108,title:l,text:d,steps:u};export{n as country,h as default,o as id,s as minutes,a as region,r as servings,i as slug,u as steps,d as text,l as title};